const { commandFactory } = commands;
const newItemCommand = commandFactory('NewItem', options);
const itemNode = await newItemCommand.execute();
if (!itemNode) {
	return null;
}

let openItemOptions = { ...options, itemNode };
const metadata = ArasModules.metadata.itemType;
if (metadata.isPolymorphic(options.itemType.id)) {
	const itemTypeName = itemNode.getAttribute('type');
	const itemType = await metadata.getItemType(itemTypeName);
	openItemOptions = { ...openItemOptions, itemType, itemTypeName };
}

const openCommand = commandFactory('OpenItem', openItemOptions);
return openCommand.execute();
